# owner: platform
"""Weekly timesheet rows from a list of shifts."""

from hourglass.errors import ProjectError


def _add(totals, s):
    if not s.worker.strip():
        raise ProjectError("blank worker name")
    n, m = totals.get(s.worker, (0, 0))
    totals[s.worker] = (n + 1, m + s.span.minutes)


def _tally(shifts):
    totals = {}
    for s in shifts:
        _add(totals, s)
    if not totals:
        raise ProjectError("no shifts")
    return totals


def _busiest(item):
    return (-item[1][1], item[0])


def _row(worker, count, minutes):
    return f"{worker}: {count} shifts, {minutes / 60:.1f} hours"


def timesheet_rows(shifts):
    """One line per worker, busiest first."""
    totals = _tally(shifts)
    ranked = sorted(totals.items(), key=_busiest)
    return [_row(w, *t) for w, t in ranked]

